import { isAllowedServerUrl, isLocalNetworkHost } from './hostGuard';

/**
 * Pairing / connection links for extension servers (contract §3.7).
 *
 * Canonical (the only format generated by the PC):
 *   tatakai://extensionserver/connect?server=<origin>&code=<code>
 * Also accepted for compatibility:
 *   /extensionserver/connect?server=…&code=…   (route after Capacitor appUrlOpen)
 *   https://tatakai.me/connect-server?server=…&code=…  and  /connect-server?…
 *   /extensionserver/<encodeURIComponent(url)>[?pass=…]  (old format)
 *   a bare server origin (http://192.168.1.20:8090, or its /server/ dashboard URL)
 *
 * Errors are thrown as `Error(code)`: `invalid_link`, `invalid_url` or
 * `insecure_host` (the UI maps them to `extensionServerClient.errors.*`).
 * Pure module (no DOM) so it can be unit tested on its own.
 */

export interface ServerLink { server: string; code?: string; password?: string }

/** One-time pairing codes: non-empty, at most 128 chars of `[A-Za-z0-9_-]`. */
export const PAIRING_CODE_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const LEGACY_WEB_HOSTS = new Set(['tatakai.me', 'www.tatakai.me', 'app.tatakai.me']);

/**
 * Normalize a server address to its origin (`scheme://host[:port]`). A missing
 * scheme becomes `http://` for local-network hosts and `https://` otherwise.
 * Throws `invalid_url` for anything with credentials, a path, query or hash,
 * and `insecure_host` when the host guard (§3.8) rejects it.
 */
export function normalizeServerOrigin(value: string, { allowDashboardPath = false } = {}): string {
  let raw = String(value ?? '').trim();
  if (!raw) throw new Error('invalid_url');
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)) {
    const host = raw.split(/[/?#]/)[0].replace(/:\d+$/, '');
    raw = (isLocalNetworkHost(host) ? 'http://' : 'https://') + raw;
  }
  let url: URL;
  try { url = new URL(raw); } catch { throw new Error('invalid_url'); }
  const pathOk = ['', '/'].includes(url.pathname) || (allowDashboardPath && /^\/server\/?$/.test(url.pathname));
  if (!['https:', 'http:'].includes(url.protocol) || !url.hostname || url.username || url.password || url.search || url.hash || !pathOk) {
    throw new Error('invalid_url');
  }
  if (!isAllowedServerUrl(url.origin)) throw new Error('insecure_host');
  return url.origin;
}

function originFromLink(value: string | null): string {
  if (!value) throw new Error('invalid_link');
  try { return normalizeServerOrigin(value); } catch (error) {
    throw new Error(error instanceof Error && error.message === 'insecure_host' ? 'insecure_host' : 'invalid_link');
  }
}

function codeFromLink(value: string | null, required: boolean): string | undefined {
  const code = String(value ?? '').trim();
  if (!code) { if (required) throw new Error('invalid_link'); return undefined; }
  if (!PAIRING_CODE_PATTERN.test(code)) throw new Error('invalid_link');
  return code;
}

/** Split any accepted link into the in-app path and its query, or null when it is not one. */
function toLinkPath(input: string): { path: string; params: URLSearchParams } | null {
  if (input.startsWith('/')) {
    const url = new URL(input, 'http://link.invalid');
    return { path: url.pathname, params: url.searchParams };
  }
  let url: URL;
  try { url = new URL(input); } catch { return null; }
  if (url.protocol === 'tatakai:') {
    // `tatakai://extensionserver/connect` → host `extensionserver` + pathname `/connect`.
    const host = url.host.toLowerCase();
    const path = host ? `/${host}${url.pathname}` : url.pathname.startsWith('/') ? url.pathname : `/${url.pathname}`;
    return { path, params: url.searchParams };
  }
  if (url.protocol === 'https:' && LEGACY_WEB_HOSTS.has(url.hostname.toLowerCase()) && (url.pathname === '/connect-server' || url.pathname.startsWith('/extensionserver/'))) {
    return { path: url.pathname, params: url.searchParams };
  }
  return null;
}

/** Parse a pairing or connection link. Throws `invalid_link` / `insecure_host`. */
export function parseServerLink(rawInput: string): ServerLink {
  const input = String(rawInput ?? '').trim();
  if (!input) throw new Error('invalid_link');
  const link = toLinkPath(input);
  if (!link) {
    // A plain server address (or its dashboard URL) pasted on its own.
    if (/^https?:\/\//i.test(input)) {
      try { return { server: normalizeServerOrigin(input, { allowDashboardPath: true }) }; } catch (error) {
        throw new Error(error instanceof Error && error.message === 'insecure_host' ? 'insecure_host' : 'invalid_link');
      }
    }
    throw new Error('invalid_link');
  }
  const path = link.path.replace(/\/+$/, '');
  if (path === '/extensionserver/connect') {
    return { server: originFromLink(link.params.get('server')), code: codeFromLink(link.params.get('code'), true) };
  }
  if (path === '/connect-server') {
    const server = originFromLink(link.params.get('server')), code = codeFromLink(link.params.get('code'), false);
    return code ? { server, code } : { server };
  }
  if (path.startsWith('/extensionserver/')) {
    let raw = path.slice('/extensionserver/'.length);
    if (!raw || raw === 'confirm') throw new Error('invalid_link');
    try { raw = decodeURIComponent(raw); } catch { throw new Error('invalid_link'); }
    const password = link.params.get('pass') || undefined;
    return { server: originFromLink(raw), ...(password ? { password } : {}) };
  }
  throw new Error('invalid_link');
}

/**
 * Parse what a user pasted in "Paste pairing link": a full link, a server
 * address, or just the one-time code (paired with `fallbackServer`, usually the
 * address field). Throws like {@link parseServerLink}.
 */
export function parsePairingInput(rawInput: string, fallbackServer = ''): ServerLink {
  const input = String(rawInput ?? '').trim();
  if (PAIRING_CODE_PATTERN.test(input) && !/^https?$/i.test(input)) {
    if (!fallbackServer.trim()) throw new Error('invalid_link');
    return { server: originFromLink(fallbackServer), code: input };
  }
  return parseServerLink(input);
}
